CREATE FUNCTION curated.parse_dcj_quarter(p_label text) RETURNS date
    LANGUAGE sql IMMUTABLE
    AS $_$
    SELECT CASE
             WHEN btrim(p_label) ~ '^((Sep|Dec) Qtr 2021|(Mar|Jun|Sep|Dec) Qtr 202[2-6])$'
             THEN date_trunc('quarter',
