    geography_key integer NOT NULL,
    time_key integer NOT NULL,
    estimated_resident_population integer NOT NULL,
    load_batch_id integer NOT NULL,
    source_row_id bigint NOT NULL,
    CONSTRAINT fact_population_estimated_resident_population_check CHECK ((estimated_resident_population >= 0))
);


--
-- Name: fact_population_population_fact_key_seq; Type: SEQUENCE; Schema: dw; Owner: -
--

ALTER TABLE dw.fact_population ALTER COLUMN population_fact_key ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME dw.fact_population_population_fact_key_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: fact_rental; Type: TABLE; Schema: dw; Owner: -
