--
-- Name: vw_rental_affordability; Type: VIEW; Schema: reporting; Owner: -
--

CREATE VIEW reporting.vw_rental_affordability AS
 WITH rent AS (
         SELECT f.rental_fact_key,
            f.geography_key,
            f.dwelling_type_key,
            g.lga_code,
            g.lga_name,
            t.date_value AS quarter_start,
            t.calendar_quarter_label,
            t.financial_year_label,
            d.standard_dwelling_type,
            d.bedroom_band,
            (d.is_all_dwellings AND d.is_all_bedrooms) AS is_lga_headline,
            f.median_weekly_rent,
            f.is_rent_suppressed,
            f.bond_lodgement_count,
            f.is_bond_count_suppressed
           FROM (((dw.fact_rental f
             JOIN dw.dim_geography g ON ((g.geography_key = f.geography_key)))
             JOIN dw.dim_time t ON ((t.time_key = f.time_key)))
             JOIN dw.dim_dwelling_type d ON ((d.dwelling_type_key = f.dwelling_type_key)))
        ), with_income AS (
         SELECT r.rental_fact_key,
            r.geography_key,
            r.dwelling_type_key,
            r.lga_code,
            r.lga_name,
            r.quarter_start,
            r.calendar_quarter_label,
            r.financial_year_label,
            r.standard_dwelling_type,
            r.bedroom_band,
            r.is_lga_headline,
            r.median_weekly_rent,
            r.is_rent_suppressed,
            r.bond_lodgement_count,
            r.is_bond_count_suppressed,
            inc.census_income_fact_key,
            inc.median_weekly_household_income,
            inc.census_vintage,
            round((((100)::numeric * r.median_weekly_rent) / inc.median_weekly_household_income), 2) AS rent_to_income_pct
           FROM (rent r
             LEFT JOIN LATERAL ( SELECT ci.census_income_fact_key,
                    ci.median_weekly_household_income,
                    ci.census_vintage
                   FROM (dw.fact_census_income ci
                     JOIN dw.dim_time ct ON ((ct.time_key = ci.time_key)))
                  WHERE ((ci.geography_key = r.geography_key) AND (ct.date_value <= r.quarter_start))
                  ORDER BY ct.date_value DESC
                 LIMIT 1) inc ON (true))
        ), with_change AS (
         SELECT w.rental_fact_key,
            w.geography_key,
            w.dwelling_type_key,
            w.lga_code,
            w.lga_name,
            w.quarter_start,
            w.calendar_quarter_label,
            w.financial_year_label,
            w.standard_dwelling_type,
            w.bedroom_band,
            w.is_lga_headline,
            w.median_weekly_rent,
            w.is_rent_suppressed,
            w.bond_lodgement_count,
            w.is_bond_count_suppressed,
            w.census_income_fact_key,
            w.median_weekly_household_income,
            w.census_vintage,
            w.rent_to_income_pct,
            lag(w.median_weekly_rent) OVER win AS prev_median_weekly_rent,
            lag(w.quarter_start) OVER win AS prev_quarter_start
           FROM with_income w
          WINDOW win AS (PARTITION BY w.geography_key, w.dwelling_type_key ORDER BY w.quarter_start)
        )
 SELECT with_change.lga_code,
    with_change.lga_name,
    with_change.calendar_quarter_label AS quarter,
    with_change.quarter_start,
    with_change.financial_year_label,
    with_change.standard_dwelling_type,
    with_change.bedroom_band,
    with_change.is_lga_headline,
    with_change.median_weekly_rent,
    with_change.is_rent_suppressed,
    with_change.bond_lodgement_count,
    with_change.is_bond_count_suppressed,
    with_change.median_weekly_household_income AS census_median_weekly_household_income,
    with_change.census_vintage AS income_reference_year,
    with_change.rent_to_income_pct,
        CASE
            WHEN (with_change.prev_quarter_start = ((with_change.quarter_start - '3 mons'::interval))::date) THEN (with_change.median_weekly_rent - with_change.prev_median_weekly_rent)
            ELSE NULL::numeric
        END AS rent_change_vs_prev_qtr,
        CASE
            WHEN (with_change.prev_quarter_start = ((with_change.quarter_start - '3 mons'::interval))::date) THEN round(((100)::numeric * ((with_change.median_weekly_rent / with_change.prev_median_weekly_rent) - (1)::numeric)), 2)
            ELSE NULL::numeric
        END AS rent_change_pct,
        CASE
            WHEN with_change.is_lga_headline THEN rank() OVER (PARTITION BY with_change.quarter_start, with_change.is_lga_headline ORDER BY with_change.rent_to_income_pct DESC NULLS LAST)
            ELSE NULL::bigint
        END AS affordability_pressure_rank,
    with_change.rental_fact_key,
    with_change.census_income_fact_key,
    (('SYNTHETIC DATA. Area-level proxy: quarterly median rent / '::text || COALESCE((with_change.census_vintage)::text, 'n/a'::text)) || ' Census median household income; not a household rent-burden measure.'::text) AS interpretation_note
   FROM with_change;


