    vw_rental_affordability.quarter,
    vw_rental_affordability.quarter_start,
    vw_rental_affordability.median_weekly_rent,
    vw_rental_affordability.census_median_weekly_household_income,
    vw_rental_affordability.income_reference_year,
    vw_rental_affordability.rent_to_income_pct,
    vw_rental_affordability.rent_change_pct
   FROM reporting.vw_rental_affordability
  WHERE vw_rental_affordability.is_lga_headline;


--
-- Name: vw_population_supply; Type: VIEW; Schema: reporting; Owner: -
--

CREATE VIEW reporting.vw_population_supply AS
 WITH years AS (
         SELECT DISTINCT t.financial_year,
            t.financial_year_label
           FROM (dw.fact_housing_supply f
             JOIN dw.dim_time t ON ((t.time_key = f.time_key)))
        ), supply AS (
         SELECT f.geography_key,
            t.financial_year,
            t.financial_year_label,
            sum(f.dwelling_count) FILTER (WHERE (s_1.stage_code = 'LODGED'::text)) AS lodged_dwellings,
            sum(f.dwelling_count) FILTER (WHERE (s_1.stage_code = 'DA_APPROVED'::text)) AS da_approved_dwellings,
            sum(f.dwelling_count) FILTER (WHERE (s_1.stage_code = 'CC_APPROVED'::text)) AS cc_approved_dwellings,
            count(*) AS stage_months_reported
           FROM ((dw.fact_housing_supply f
             JOIN dw.dim_time t ON ((t.time_key = f.time_key)))
             JOIN dw.dim_pipeline_stage s_1 ON ((s_1.pipeline_stage_key = f.pipeline_stage_key)))
          GROUP BY f.geography_key, t.financial_year, t.financial_year_label
        ), population AS (
         SELECT f.population_fact_key,
            f.geography_key,
            t.financial_year,
            f.estimated_resident_population AS erp
           FROM (dw.fact_population f
             JOIN dw.dim_time t ON ((t.time_key = f.time_key)))
        )
 SELECT g.lga_code,
    g.lga_name,
    y.financial_year_label,
    y.financial_year,
    p0.erp AS erp_start_30_june,
    p1.erp AS erp_end_30_june,
    (p1.erp - p0.erp) AS population_change,
    round(((100.0 * ((p1.erp - p0.erp))::numeric) / (NULLIF(p0.erp, 0))::numeric), 2) AS population_growth_pct,
    s.lodged_dwellings,
    s.da_approved_dwellings,
    s.cc_approved_dwellings,
    COALESCE(s.stage_months_reported, (0)::bigint) AS stage_months_reported,
    (COALESCE(s.stage_months_reported, (0)::bigint) = 36) AS is_complete_supply_year,
    round(((1000.0 * (s.da_approved_dwellings)::numeric) / (NULLIF(p1.erp, 0))::numeric), 2) AS da_approved_per_1000_residents,
    round((((p1.erp - p0.erp))::numeric / (NULLIF(s.da_approved_dwellings, 0))::numeric), 2) AS added_residents_per_da_approved_dwelling,
    p0.population_fact_key AS start_population_fact_key,
    p1.population_fact_key AS end_population_fact_key,
    (('SYNTHETIC DATA. Approvals are not completed dwellings; population and dwellings are different units. '::text ||
        CASE
            WHEN (COALESCE(s.stage_months_reported, (0)::bigint) < 36) THEN (('Supply year incomplete ('::text || COALESCE(s.stage_months_reported, (0)::bigint)) || ' of 36 stage-months). '::text)
            ELSE ''::text
        END) ||
        CASE
            WHEN ((p0.erp IS NULL) OR (p1.erp IS NULL)) THEN 'Population estimate not available for this year.'::text
            ELSE ''::text
        END) AS interpretation_note
   FROM ((((dw.dim_geography g
     CROSS JOIN years y)
     LEFT JOIN supply s ON (((s.geography_key = g.geography_key) AND (s.financial_year = y.financial_year))))
     LEFT JOIN population p1 ON (((p1.geography_key = g.geography_key) AND (p1.financial_year = y.financial_year))))
     LEFT JOIN population p0 ON (((p0.geography_key = g.geography_key) AND (p0.financial_year = (y.financial_year - 1)))))
  WHERE ((make_date((y.financial_year - 1), 7, 1) >= g.valid_from) AND ((g.valid_to IS NULL) OR (make_date((y.financial_year - 1), 7, 1) < g.valid_to)));


--
-- Name: vw_dashboard_uc2; Type: VIEW; Schema: reporting; Owner: -
--

CREATE VIEW reporting.vw_dashboard_uc2 AS
 SELECT vw_population_supply.lga_code,
    vw_population_supply.lga_name,
    vw_population_supply.financial_year,
    vw_population_supply.financial_year_label,
    vw_population_supply.erp_start_30_june,
    vw_population_supply.erp_end_30_june,
    vw_population_supply.population_change,
    vw_population_supply.population_growth_pct,
    vw_population_supply.da_approved_dwellings,
    vw_population_supply.da_approved_per_1000_residents,
    vw_population_supply.is_complete_supply_year
   FROM reporting.vw_population_supply;


--
-- Name: vw_housing_pipeline; Type: VIEW; Schema: reporting; Owner: -
--

CREATE VIEW reporting.vw_housing_pipeline AS
 WITH month_bounds AS (
         SELECT min(t_1.date_value) AS first_month,
            max(t_1.date_value) AS last_month
           FROM (dw.fact_housing_supply f_1
             JOIN dw.dim_time t_1 ON ((t_1.time_key = f_1.time_key)))
        ), months AS (
         SELECT t_1.time_key,
            t_1.date_value,
            t_1.month_start,
            t_1.quarter_start,
            t_1.calendar_month,
            t_1.calendar_quarter,
            t_1.calendar_quarter_label,
            t_1.calendar_year,
            t_1.financial_year,
            t_1.financial_year_label
           FROM (dw.dim_time t_1
             CROSS JOIN month_bounds b)
          WHERE ((t_1.date_value = t_1.month_start) AND ((t_1.date_value >= b.first_month) AND (t_1.date_value <= b.last_month)))
        )
 SELECT g.lga_code,
    g.lga_name,
    t.date_value AS month_start,
    to_char((t.date_value)::timestamp with time zone, 'Mon YYYY'::text) AS month_label,
    t.calendar_quarter_label,
    t.financial_year_label,
    sum(f.dwelling_count) FILTER (WHERE (s.stage_code = 'LODGED'::text)) AS lodged_dwellings,
    sum(f.dwelling_count) FILTER (WHERE (s.stage_code = 'DA_APPROVED'::text)) AS da_approved_dwellings,
    sum(f.dwelling_count) FILTER (WHERE (s.stage_code = 'CC_APPROVED'::text)) AS cc_approved_dwellings,
    count(f.housing_supply_fact_key) AS stages_reported,
    ('SYNTHETIC DATA. Independent counts per stage for the month, not the same projects moving '::text || 'through a workflow; local completions are not available (statewide only in the source).'::text) AS interpretation_note
   FROM (((dw.dim_geography g
     CROSS JOIN months t)
     LEFT JOIN dw.fact_housing_supply f ON (((f.geography_key = g.geography_key) AND (f.time_key = t.time_key))))
     LEFT JOIN dw.dim_pipeline_stage s ON ((s.pipeline_stage_key = f.pipeline_stage_key)))
  WHERE ((t.date_value >= g.valid_from) AND ((g.valid_to IS NULL) OR (t.date_value < g.valid_to)))
  GROUP BY g.lga_code, g.lga_name, t.date_value, t.calendar_quarter_label, t.financial_year_label;


--
-- Name: vw_dashboard_uc3; Type: VIEW; Schema: reporting; Owner: -
--

CREATE VIEW reporting.vw_dashboard_uc3 AS
 SELECT vw_housing_pipeline.lga_code,
    vw_housing_pipeline.lga_name,
    vw_housing_pipeline.month_start,
    vw_housing_pipeline.month_label,
    vw_housing_pipeline.lodged_dwellings,
    vw_housing_pipeline.da_approved_dwellings,
    vw_housing_pipeline.cc_approved_dwellings,
    vw_housing_pipeline.stages_reported
   FROM reporting.vw_housing_pipeline;


