--
-- Name: vw_lineage; Type: VIEW; Schema: reporting; Owner: -
--

CREATE VIEW reporting.vw_lineage AS
 SELECT 'fact_rental'::text AS fact_table,
    f.rental_fact_key AS fact_key,
    g.lga_code,
    g.lga_name,
    t.date_value AS period_start,
    sf.source_system,
    sf.target_table AS source_table,
    f.source_row_id,
    s.source_row_number,
    NULL::text AS source_column,
    sf.source_file_name,
    sf.content_md5,
    f.load_batch_id,
    b.started_at AS batch_started_at,
    s.is_synthetic
   FROM (((((dw.fact_rental f
     JOIN dw.dim_geography g ON ((g.geography_key = f.geography_key)))
     JOIN dw.dim_time t ON ((t.time_key = f.time_key)))
     JOIN src_rental.rent_lga_quarter_raw s ON ((s.source_row_id = f.source_row_id)))
     JOIN control.source_file sf ON ((sf.source_file_id = s.source_file_id)))
     JOIN control.load_batch b ON ((b.load_batch_id = f.load_batch_id)))
UNION ALL
 SELECT 'fact_census_income'::text AS fact_table,
    f.census_income_fact_key AS fact_key,
    g.lga_code,
    g.lga_name,
    t.date_value AS period_start,
    sf.source_system,
    sf.target_table AS source_table,
    f.source_row_id,
    s.source_row_number,
    NULL::text AS source_column,
    sf.source_file_name,
    sf.content_md5,
    f.load_batch_id,
    b.started_at AS batch_started_at,
    s.is_synthetic
   FROM (((((dw.fact_census_income f
     JOIN dw.dim_geography g ON ((g.geography_key = f.geography_key)))
     JOIN dw.dim_time t ON ((t.time_key = f.time_key)))
     JOIN src_census.census_lga_income_raw s ON ((s.source_row_id = f.source_row_id)))
     JOIN control.source_file sf ON ((sf.source_file_id = s.source_file_id)))
     JOIN control.load_batch b ON ((b.load_batch_id = f.load_batch_id)))
UNION ALL
 SELECT 'fact_population'::text AS fact_table,
    f.population_fact_key AS fact_key,
    g.lga_code,
    g.lga_name,
    t.date_value AS period_start,
    sf.source_system,
    sf.target_table AS source_table,
    f.source_row_id,
    s.source_row_number,
    NULL::text AS source_column,
    sf.source_file_name,
    sf.content_md5,
    f.load_batch_id,
    b.started_at AS batch_started_at,
    s.is_synthetic
   FROM (((((dw.fact_population f
     JOIN dw.dim_geography g ON ((g.geography_key = f.geography_key)))
     JOIN dw.dim_time t ON ((t.time_key = f.time_key)))
     JOIN src_population.population_lga_year_raw s ON ((s.source_row_id = f.source_row_id)))
     JOIN control.source_file sf ON ((sf.source_file_id = s.source_file_id)))
     JOIN control.load_batch b ON ((b.load_batch_id = f.load_batch_id)))
UNION ALL
 SELECT 'fact_housing_supply'::text AS fact_table,
    f.housing_supply_fact_key AS fact_key,
    g.lga_code,
    g.lga_name,
    t.date_value AS period_start,
    sf.source_system,
    sf.target_table AS source_table,
    f.source_row_id,
    s.source_row_number,
    f.source_column,
    sf.source_file_name,
    sf.content_md5,
    f.load_batch_id,
    b.started_at AS batch_started_at,
    s.is_synthetic
   FROM (((((dw.fact_housing_supply f
     JOIN dw.dim_geography g ON ((g.geography_key = f.geography_key)))
     JOIN dw.dim_time t ON ((t.time_key = f.time_key)))
     JOIN src_housing.housing_supply_lga_month_raw s ON ((s.source_row_id = f.source_row_id)))
     JOIN control.source_file sf ON ((sf.source_file_id = s.source_file_id)))
     JOIN control.load_batch b ON ((b.load_batch_id = f.load_batch_id)));


